<script lang="ts">
	/**
	 * El logo, en línea y como vector.
	 *
	 * ⚠️ **Era un PNG y sobre fondo claro se veía sucio, por dos razones a la vez.**
	 *
	 * La primera es que el ráster lleva **un contorno azul oscuro y una sombra
	 * horneados en los píxeles**: medido, los cuatro colores más frecuentes del
	 * fichero son ese contorno (`#104040` y familia), no la marca. Sobre negro
	 * desaparece; sobre blanco es el borrón que se ve. La segunda es que los tonos
	 * de la marca son neón — `#5eead4` da **1,35:1 sobre `#f4f4f9`** —, así que en
	 * tema claro lo único que se leía bien era justamente la suciedad.
	 *
	 * Vectorizado del master ráster que había antes —contornos **y huecos**—: sin los
	 * huecos cada platillo de la balanza sale macizo, una gota rellena en vez de un
	 * cuenco dibujado, y el anillo de la C pierde su banda doble.
	 *
	 * ⚠️ **El degradado viene de tokens, y por eso el logo va en línea y no como
	 * `<img src="/logo.svg">`.** Un SVG cargado como imagen no puede leer las
	 * variables CSS de la página, así que no podría seguir al tema. Los PNG de
	 * `static/` siguen existiendo para lo que no es la app —el `logo` de los datos
	 * estructurados, los iconos de la PWA— y se rinden desde `assets/logo.svg`.
	 */

	interface Props {
		/** Lado en píxeles; el viewBox es cuadrado. */
		size?: number;
		/** Texto alternativo. Vacío = decorativo, cuando el nombre ya va al lado. */
		alt?: string;
		clase?: string;
	}

	let { size = 48, alt = '', clase = '' }: Props = $props();

	/**
	 * ⚠️ Un id por instancia. En la landing hay dos logos en el mismo documento
	 * (barra y pie) y dos degradados con el mismo id colisionan: el segundo
	 * elemento resuelve contra el primero. Es el mismo problema que
	 * `Sparkline.svelte` ya documenta para sus degradados.
	 */
	const gradId = `cb-logo-${Math.random().toString(36).slice(2, 9)}`;
</script>

